    return {
        appId: BOOKINGS_APP_ID,
        hidden: false,
        ...(slug ? { "mainSlug.name": slug } : {}),
        ...(categoryId ? { "category.id": categoryId } : {}),
        ...(locationId === OTHER_LOCATIONS_ID
